from pathlib import Path

root = Path("jarvis0215")

def replace_once(path, old, new):
    p = root / path
    text = p.read_text(encoding="utf-8")
    if old not in text:
        raise SystemExit(f"pattern not found in {path}")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")

